/** Look up a UI string; falls back to English (the key) and substitutes `{placeholders}`. */
export function translate(lang: Lang, key: string, vars?: Record<string, string | number>): string {
  let text = lang === "en" ? key : (UI[lang]?.[key] ?? key);
  if (vars) {
    for (const [k, v] of Object.entries(vars)) text = text.split(`{${k}}`).join(String(v));
  }
  return text;
}

/** Translate host-written content if we have an exact translation; returns [text, wasTranslated]. */
export function translateContent(lang: Lang, text: string): [string, boolean] {
  if (lang === "en") return [text, false];
  const hit = CONTENT[lang]?.[text.trim()];
  return hit ? [hit, true] : [text, false];
}
